import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"know-me","description":"","frontmatter":{},"headers":[],"relativePath":"skills/know-me.md","filePath":"skills/know-me.md"}'),d={name:"skills/know-me.md"};function l(n,t,i,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="know-me" tabindex="-1">know-me <a class="header-anchor" href="#know-me" aria-label="Permalink to &quot;know-me&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>know-me</td></tr><tr><td>說明</td><td>了解使用者偏好與背景。讀取記憶檔案以提供個人化的協助。</td></tr><tr><td>來源目錄</td><td><code>skills/know-me/</code></td></tr></tbody></table><hr><h1 id="撰寫高品質自動記憶" tabindex="-1">撰寫高品質自動記憶 <a class="header-anchor" href="#撰寫高品質自動記憶" aria-label="Permalink to &quot;撰寫高品質自動記憶&quot;">​</a></h1><p>記憶的存在是為了改變未來的行為。每一筆記憶都必須通過一個測試：<strong>「未來的 Claude session 是否會因為這筆記憶的存在而做出不同（更好）的決策？」</strong></p><h2 id="快速參考" tabindex="-1">快速參考 <a class="header-anchor" href="#快速參考" aria-label="Permalink to &quot;快速參考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原則</th><th>規則</th></tr></thead><tbody><tr><td>可採取行動</td><td>規定具體行動，而非觀察</td></tr><tr><td>具體</td><td>套用時無需額外解讀</td></tr><tr><td>原子性</td><td>每個主題檔案只包含一個概念</td></tr><tr><td>情境化原因</td><td>回饋/專案記憶包含 <strong>Why</strong>（為何）+ <strong>How to apply</strong>（如何應用）</td></tr><tr><td>絕對日期</td><td>立即將相對日期轉換為絕對日期</td></tr></tbody></table><h2 id="_200-行限制" tabindex="-1">200 行限制 <a class="header-anchor" href="#_200-行限制" aria-label="Permalink to &quot;200 行限制&quot;">​</a></h2><ul><li><code>MEMORY.md</code> = 簡潔索引（每個 session 會載入前 200 行）</li><li>主題檔案 = 詳細內容，按需讀取</li><li>每行索引是一個指標，而非內容本身</li></ul><h2 id="不應儲存的內容" tabindex="-1">不應儲存的內容 <a class="header-anchor" href="#不應儲存的內容" aria-label="Permalink to &quot;不應儲存的內容&quot;">​</a></h2><p>如果可以用 <code>grep</code>、<code>git log</code> 或讀取檔案取得，就不要記憶。包括：程式碼模式、檔案路徑、git 歷史、CLAUDE.md/rules 中已有的內容、臨時任務狀態。</p><h2 id="記憶生命週期" tabindex="-1">記憶生命週期 <a class="header-anchor" href="#記憶生命週期" aria-label="Permalink to &quot;記憶生命週期&quot;">​</a></h2><ol><li><strong>建立前</strong> — 先檢查 MEMORY.md 是否有既有條目；更新，不要重複</li><li><strong>何時更新</strong> — 使用者修正指引、情境改變、記憶不正確時</li><li><strong>何時刪除</strong> — 已提升至 CLAUDE.md/rules、截止日已過、記憶有誤時</li><li><strong>何時分割</strong> — 主題檔案超過 50 行時</li></ol><h2 id="深度參考" tabindex="-1">深度參考 <a class="header-anchor" href="#深度參考" aria-label="Permalink to &quot;深度參考&quot;">​</a></h2><p>完整的記憶品質指南、審核清單與範例，請參見： <code>evolve-config/ref-memory-quality</code>（由 memory-reviewer agent 預載）</p><h2 id="生態系健康" tabindex="-1">生態系健康 <a class="header-anchor" href="#生態系健康" aria-label="Permalink to &quot;生態系健康&quot;">​</a></h2><p>使用 <code>/evolve</code> 執行完整的設定生態系審核，包含記憶品質檢查。</p>',17)])])}const b=e(d,[["render",l]]);export{u as __pageData,b as default};
